+      result: true
+    });
+  });
+  it("Labels num", () => {
+    expect(isDomainValid("example")).toEqual({
+      result: false,
+      message: "Domain has to contain at least two labels"
+    });
+    expect(isDomainValid("example.technology")).toEqual({
+      result: true
+    });
+  });
+  it("Labels", () => {
+    expect(isDomainValid("ocai6oiz9ezsrgjvrsdo1lakvxvqrtpcwixeljjyknbqjnyo9ajryikbk2kswtwo.com")).toEqual({
+      result: false,
+      message: "Label ocai6oiz9ezsrgjvrsdo1lakvxvqrtpcwixeljjyknbqjnyo9ajryikbk2kswtwo contains more than 63 characters"
+    });
+    expect(isDomainValid("ocai6oiz9ezsrgjvrsdo1lakvxvqrtpcwixeljjyknbqjnyo9ajryikbk2kswtw.de")).toEqual({
+      result: true
+    });
+    expect(isDomainValid("exam_ple.com")).toEqual({
+      result: false,
+      message: "Label exam_ple contains a invalid character(s)"
+    });
+    expect(isDomainValid("-example.com")).toEqual({
+      result: false,
+      message: "Label -example begins with hyphen"
+    });
+    expect(isDomainValid("example-.com")).toEqual({
+      result: false,
+      message: "Label example- ends with hyphen"
+    });
+    expect(isDomainValid("exa--mple.com")).toEqual({
+      result: false,
+      message: "Label exa--mple contains consecutive hyphens"
+    });
+    expect(isDomainValid("exa-mple.com")).toEqual({
+      result: true
+    });
+    expect(isDomainValid("xn--examxn--ple.com")).toEqual({
+      result: false,
+      message: "Label xn--examxn--ple contains more than one xn-- pointers"
+    });
+    expect(isDomainValid("exampxn--le.com")).toEqual({
+      result: false,
+      message: "Label exampxn--le contains xn-- pointer not at the very beginning"
+    });
+    expect(isDomainValid("xn--c1yn--36f.com")).toEqual({
+      result: false,
+      message: "Label xn--c1yn--36f contains consecutive hyphens"
+    });
